local config = {
  str_homestory_N24diaoyu_90050101_1_dialog_content = "¡Vice!",
  str_homestory_N24diaoyu_90050101_2_dialog_content = "Hola, PlayerName.",
  str_homestory_N24diaoyu_90050101_3_dialog_content = "¿Todavía te gusta atrapar insectos o recolectar conchas marinas para agregarlas a tu colección de especímenes?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050101_4_dialog_content = "No he estado haciendo eso por un tiempo ahora.",
  str_homestory_N24diaoyu_90050101_5_dialog_content = "Claro, hay muchas plantas y animales diferentes en Cloud Gardens, pero aún envejece después de hacerlo todos los días, de día a noche.",
  str_homestory_N24diaoyu_90050101_6_dialog_content = "Oh, todos los días del día a la noche? Seguro que has sido uno con la naturaleza, ¿no es así? PlayerName?",
  str_homestory_N24diaoyu_90050101_7_dialog_content = "¿Qué planeas hacer a continuación?",
  str_homestory_N24diaoyu_90050101_8_dialog_content = "¿Qué tal un museo que exhiba todas las plantas y animales en Cloud Gardens para que todos los visitantes aurorianos las vean?",
  str_homestory_N24diaoyu_90050101_9_dialog_content = "<sprite=emo_dianzan size=60 />¡Es una gran idea! Déjame pensar...",
  str_homestory_N24diaoyu_90050101_10_dialog_content = "Pero va a costar mucho dinero.<sprite=emo_baiyebi size=60 />",
  str_homestory_N24diaoyu_90050101_11_dialog_content = "Por supuesto. Un museo necesita mucho equipamiento para proteger sus colecciones.",
  str_homestory_N24diaoyu_90050101_12_dialog_content = "Como sistemas de control de temperatura, humedad y...",
  str_homestory_N24diaoyu_90050101_13_dialog_content = "Esperar. ¿Ese era Barton hace un momento?",
  str_homestory_N24diaoyu_90050101_14_dialog_content = "¿Eh? ¿Alguien pasó por nosotros? No estaba prestando atención.",
  str_homestory_N24diaoyu_90050101_15_dialog_content = "No importa. Probablemente solo vi algo con el rabillo del ojo que no estaba allí.",
  str_homestory_N24diaoyu_90050101_16_dialog_content = "<sprite=emo_laba size=60 />PlayerName! PlayerName!",
  str_homestory_N24diaoyu_90050101_17_dialog_content = "fia?",
  str_homestory_N24diaoyu_90050101_18_dialog_content = "Ven ayuda, PlayerName! ¡Necesito que me ayudes con muchas cosas!",
  str_homestory_N24diaoyu_90050101_19_dialog_content = "¿Qué, ni siquiera vas a fingir que tienes un \"pequeño\" favor que pedir ahora?",
  str_homestory_N24diaoyu_90050101_20_dialog_content = "Solo viene directo a mí con todos tus problemas ahora...<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050101_21_dialog_content = "Um, pensé que habíamos pasado de andarnos por las ramas, PlayerName!",
  str_homestory_N24diaoyu_90050101_22_dialog_content = "Estás bien. Entonces déjame rechazarte aquí mismo, ahora mismo.",
  str_homestory_N24diaoyu_90050101_23_dialog_content = "¿Eh? ¡Por qué!<sprite=emo_xinsui size=60 />",
  str_homestory_N24diaoyu_90050101_24_dialog_content = "estoy ocupado Necesito construir un museo en Cloud Gardens.",
  str_homestory_N24diaoyu_90050101_25_dialog_content = "Esto es algo enorme para Cloud Gardens. No tengo tiempo para jugar contigo.",
  str_homestory_N24diaoyu_90050101_26_dialog_content = "¿¡Ayudarme es \"jugar\"!?",
  str_homestory_N24diaoyu_90050101_27_dialog_content = "<sprite=emo_shengqi size=60 />De acuerdo PlayerName¡Entonces no te ayudaré la próxima vez! ¡Te vas a arrepentir de esto, tonto!",
  str_homestory_N24diaoyu_90050101_28_dialog_content = "Ella escapó. ¿Está realmente bien dejar a Fia sola así?",
  str_homestory_N24diaoyu_90050101_29_dialog_content = "No puedo consentirla haciendo todo por ella.",
  str_homestory_N24diaoyu_90050101_30_dialog_content = "En un momento u otro, tendrá que aprender a resolver las cosas por su cuenta. Le daré un empujón extra cuando realmente lo necesite.",
  str_homestory_N24diaoyu_90050101_31_dialog_content = "Así es como ella crece.",
  str_homestory_N24diaoyu_90050101_32_dialog_content = "<sprite=emo_chidai size=60 />Vaya... Realmente te estás convirtiendo en un gran mentor. PlayerName.",
  str_homestory_N24diaoyu_90050101_33_dialog_content = "Es eso, o eso es solo palabrería de tu parte.",
  str_homestory_N24diaoyu_90050101_34_dialog_content = "Jejeje...",
  str_homestory_N24diaoyu_90050101_35_dialog_content = "¿Eh? ¿Fleur acaba de pasar corriendo?",
  str_homestory_N24diaoyu_90050101_36_dialog_content = "Barton, Fia y ahora Fleur... ¿Por qué tienen tanta prisa?",
  str_homestory_N24diaoyu_90050101_37_dialog_content = "No puedo soportar esto. Tengo que alcanzarlos y ver qué está pasando.",
  str_homestory_N24diaoyu_90050102_1_dialog_content = "<sprite=emo_hanshui size=60 />¡Uf, puf!",
  str_homestory_N24diaoyu_90050102_2_dialog_content = "PlayerName, será mejor que te tomes un respiro antes de que te derrumbes.",
  str_homestory_N24diaoyu_90050102_3_dialog_content = "¿Vicio? PlayerName? ¿Por qué ustedes dos jadean así?",
  str_homestory_N24diaoyu_90050102_4_dialog_content = "Yo... estoy tratando de alcanzar a Fleur.",
  str_homestory_N24diaoyu_90050102_5_dialog_content = "Y estoy tratando de ser un buen amigo para él.",
  str_homestory_N24diaoyu_90050102_6_dialog_content = "¿Cómo...? ¿Cómo puede Fleur correr tan rápido? No parece del tipo atlético.",
  str_homestory_N24diaoyu_90050102_7_dialog_content = "¿En serio? De hecho, veo a Fleur trotando por Cloud Gardens con bastante frecuencia.",
  str_homestory_N24diaoyu_90050102_8_dialog_content = "¿Qué? ¿Es eso lo que realmente es? <sprite=emo_tanqi size=60 />Podría haberme engañado...",
  str_homestory_N24diaoyu_90050102_9_dialog_content = "Entonces, ¿por qué estás detrás de Fleur? PlayerName?",
  str_homestory_N24diaoyu_90050102_10_dialog_content = "O... ¿solo lo haces por diversión?",
  str_homestory_N24diaoyu_90050102_11_dialog_content = "¿Por diversión? ¡De ninguna manera!",
  str_homestory_N24diaoyu_90050102_12_dialog_content = "Bueno... No es que haya nada importante. Sólo quiero saber por qué tiene prisa.",
  str_homestory_N24diaoyu_90050102_13_dialog_content = "Esa es la definición misma de \"por diversión\", ¿no?<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050102_14_dialog_content = "Bromas aparte, creo que sé lo que está tramando Fleur.",
  str_homestory_N24diaoyu_90050102_15_dialog_content = "¿En serio? ¿Tú haces?",
  str_homestory_N24diaoyu_90050102_16_dialog_content = "Sí. A juzgar por lo que lleva puesto, probablemente vaya a pescar.",
  str_homestory_N24diaoyu_90050102_17_dialog_content = "<sprite=emo_sikao size=60 />Pescar...?",
  str_homestory_N24diaoyu_90050102_18_dialog_content = "Sí. Escuché que es un evento organizado conjuntamente por un editor y muchos gremios de Umbraton, sugerido por un auroriano del desierto de Rediesel.",
  str_homestory_N24diaoyu_90050102_19_dialog_content = "Este \"<color=#FFB400>Una captura extraordinaria</color>\"Concurso de pesca resulta ser todo un éxito. Los concursantes se llaman <color=#FFB400>pescadores</color>.",
  str_homestory_N24diaoyu_90050102_20_dialog_content = "Fleur debe haberse unido al concurso y está tratando de competir contra otros pescadores.",
  str_homestory_N24diaoyu_90050102_21_dialog_content = "El gran premio de este tipo de eventos debe ser un recuerdo o algo... Simplemente no esperaba que Fleur estuviera interesada en esto.",
  str_homestory_N24diaoyu_90050102_22_dialog_content = "No creo que ese sea el caso. Se dice que el premio es un <color=#FFB400>caña de pescar de oro puro cubierta con Lumamber</color>.",
  str_homestory_N24diaoyu_90050102_23_dialog_content = "¿Oro puro, dices...?",
  str_homestory_N24diaoyu_90050102_24_dialog_content = "Y cubierto con Lumamber...",
  str_homestory_N24diaoyu_90050102_25_dialog_content = "<sprite=emo_mojing size=60 />¡Ejem! Carleen, debes saber que la gente en Cloud Gardens me llama \"Dragonwave Angler\".",
  str_homestory_N24diaoyu_90050102_26_dialog_content = "¡De ninguna manera dejaré que me quiten ningún pez!",
  str_homestory_N24diaoyu_90050102_27_dialog_content = "(¡Si gano, tendré los fondos para construir un museo!<sprite=emo_baiyebi size=60 />)",
  str_homestory_N24diaoyu_90050102_28_dialog_content = "¿Quieres unirte?",
  str_homestory_N24diaoyu_90050102_29_dialog_content = "Si lo hace, tendrá que ponerse en contacto con Bethel, que representa a los gremios que organizan este evento...",
  str_homestory_N24diaoyu_90050102_30_dialog_content = "<sprite=emo_dianzan size=60 />¡Entiendo! ¡Gracias, Carleen!",
  str_homestory_N24diaoyu_90050102_31_dialog_content = "Ni siquiera había terminado todavía.",
  str_homestory_N24diaoyu_90050102_32_dialog_content = "Bueno... ¿Por qué no nos unimos al concurso con PlayerName?",
  str_homestory_N24diaoyu_90050102_33_dialog_content = "¿Eh?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050103_1_dialog_content = "Bethel!",
  str_homestory_N24diaoyu_90050103_2_dialog_content = "PlayerName, Vicio. ¡Ah, y Lady Carleen también!",
  str_homestory_N24diaoyu_90050103_3_dialog_content = "Mucho tiempo sin verlo. ¿Terminaste la novela que te recomendé, Vice?",
  str_homestory_N24diaoyu_90050103_4_dialog_content = "¡Casi! ¡Disfruto cómo realmente profundiza en las emociones del protagonista!",
  str_homestory_N24diaoyu_90050103_5_dialog_content = "¡Y su relación con Genie, su compañero mecánico, también es bastante conmovedora!<sprite=emo_caitiao size=60 />",
  str_homestory_N24diaoyu_90050103_6_dialog_content = "<sprite=emo_aixin size=60 />¿Derecha? ¿Derecha? Una relación así es tan platónica...",
  str_homestory_N24diaoyu_90050103_7_dialog_content = "¡Ejem!",
  str_homestory_N24diaoyu_90050103_8_dialog_content = "Vice, no estamos aquí para hablar de la novela...",
  str_homestory_N24diaoyu_90050103_9_dialog_content = "¡En realidad estamos aquí porque queremos inscribirnos en el concurso de pesca!",
  str_homestory_N24diaoyu_90050103_10_dialog_content = "¡Vaya! ¡No sabía que todos ustedes estaban interesados en la pesca!",
  str_homestory_N24diaoyu_90050103_11_dialog_content = "¿Es una broma? ¡Soy el renombrado pescador Dragonwave de Cloud Gardens!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050103_12_dialog_content = "Estoy muy interesado en el gran premio!<sprite=emo_baiyebi size=60 />",
  str_homestory_N24diaoyu_90050103_13_dialog_content = "Bueno... estoy aquí porque lo son.",
  str_homestory_N24diaoyu_90050103_14_dialog_content = "Ya veo. Pero, lo siento, no he oído nada sobre un Dragonwave Angler.",
  str_homestory_N24diaoyu_90050103_15_dialog_content = "¡Oh, el mundo sabrá mi nombre una vez que me lleve a casa el gran premio!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050103_16_dialog_content = "Correcto... Eso sería algo por lo que esperar. Sin embargo...",
  str_homestory_N24diaoyu_90050103_17_dialog_content = "¿Mmm?",
  str_homestory_N24diaoyu_90050103_18_dialog_content = "El plazo de inscripción ha finalizado.",
  str_homestory_N24diaoyu_90050103_19_dialog_content = "<sprite=emo_xinsui size=60 />¿¡Qué!?",
  str_homestory_N24diaoyu_90050103_20_dialog_content = "PlayerName parece tan decepcionado. ¿Es un gran golpe para él no poder unirse al concurso?",
  str_homestory_N24diaoyu_90050103_21_dialog_content = "Probablemente... quiero decir, incluso estaba tratando de encontrar nombres para su casting.",
  str_homestory_N24diaoyu_90050103_22_dialog_content = "Bueno... Hay una manera.",
  str_homestory_N24diaoyu_90050103_23_dialog_content = "¿¡Hay una manera!?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050103_24_dialog_content = "Quiero decir, es un concurso que solo será divertido si hay muchos concursantes.",
  str_homestory_N24diaoyu_90050103_25_dialog_content = "Y también es mi trabajo asegurarme de que los buenos pescadores tengan la oportunidad de brillar.",
  str_homestory_N24diaoyu_90050103_26_dialog_content = "Pero primero tendrán que probarse a sí mismos ante mí.",
  str_homestory_N24diaoyu_90050103_27_dialog_content = "¿Qué estas sugeriendo?",
  str_homestory_N24diaoyu_90050103_28_dialog_content = "Cinco Knifefish por persona.",
  str_homestory_N24diaoyu_90050103_29_dialog_content = "¡El primero que regrese con cinco también recibe un regalo sorpresa!",
  str_homestory_N24diaoyu_90050103_30_dialog_content = "¡Entiendo! ¡Vamos, Vice, Carleen!",
  str_homestory_N24diaoyu_90050104_1_dialog_content = "¿Seguro que tienes suficiente?",
  str_homestory_N24diaoyu_90050104_2_dialog_content = "¡Sí! ({1}/{2})",
  str_homestory_N24diaoyu_90050104_3_dialog_content = "Sólo faltan unos pocos más. ¡Sólo un momento!",
  str_homestory_N24diaoyu_90050104_4_dialog_content = "¡Buena suerte!",
  str_homestory_N24diaoyu_90050104_5_dialog_content = "Bueno, eso es rápido.",
  str_homestory_N24diaoyu_90050104_6_dialog_content = "<sprite=emo_dianzan size=60 />Parece PlayerName realmente no estaba bromeando.",
  str_homestory_N24diaoyu_90050104_7_dialog_content = "Jejeje! ¡Por supuesto! ¡Regresé aquí tan pronto como atrapé el pez!",
  str_homestory_N24diaoyu_90050104_8_dialog_content = "¿Aún no han vuelto?",
  str_homestory_N24diaoyu_90050104_9_dialog_content = "No. Bueno, como prometí, obtienes la primera selección de tu caña de pescar, PlayerName.",
  str_homestory_N24diaoyu_90050104_10_dialog_content = "¿Ese es el regalo sorpresa que mencionaste?",
  str_homestory_N24diaoyu_90050104_11_dialog_content = "Sí. Preparamos muchas cañas de pescar diferentes para nuestros concursantes. Solo un pescador aprobado puede sostener una de nuestras cañas de pescar certificadas.",
  str_homestory_N24diaoyu_90050104_12_dialog_content = "Entonces, ¿qué tendrás? ¿Una caña de pescar de fuego, agua o hierba?",
  str_homestory_N24diaoyu_90050104_13_dialog_content = "Eh... ¿Cuál es la diferencia?",
  str_homestory_N24diaoyu_90050104_14_dialog_content = "¡Tendrás que averiguarlo por ti mismo! Tal vez te dé una habilidad especial o crezca contigo. ¡O tal vez no hay diferencia en absoluto!",
  str_homestory_N24diaoyu_90050104_15_dialog_content = "Es solo una caña de pescar, después de todo. Pero una vez que lo elijas, se convertirá en tu mejor amigo.",
  str_homestory_N24diaoyu_90050104_16_dialog_content = "Entonces elegiré...",
  str_homestory_N24diaoyu_90050104_17_option_content = "¡La caña de pescar Grass!",
  str_homestory_N24diaoyu_90050104_18_option_content = "¡La caña de pescar de fuego!",
  str_homestory_N24diaoyu_90050104_19_option_content = "¡La caña de pescar en el agua!",
  str_homestory_N24diaoyu_90050104_20_dialog_content = "¡Guau! ¡Se siente bien sostenerlo!",
  str_homestory_N24diaoyu_90050104_21_dialog_content = "<sprite=emo_tanqi size=60 />Pero no creo que tenga ninguna de esas habilidades especiales...",
  str_homestory_N24diaoyu_90050104_22_dialog_content = "Volví.",
  str_homestory_N24diaoyu_90050104_23_dialog_content = "Has vuelto, Carleen.",
  str_homestory_N24diaoyu_90050104_24_dialog_content = "Elige una caña de pescar de las dos restantes.",
  str_homestory_N24diaoyu_90050104_25_dialog_content = "Lo que sea... Cualquiera serviría.",
  str_homestory_N24diaoyu_90050104_26_dialog_content = "Ahora que tienes tu caña de pescar, ¿por qué no la pruebas?",
  str_homestory_N24diaoyu_90050104_27_dialog_content = "Comencemos la primera ronda del concurso mientras esperamos que regrese Vice.",
  str_homestory_N24diaoyu_90050104X_1_dialog_content = "PlayerName, tu caña de pescar se ve poderosa.",
  str_homestory_N24diaoyu_90050104X_2_dialog_content = "¿Estás preparado para tener un concurso conmigo primero?",
  str_homestory_N24diaoyu_90050104X_3_option_content = "Estoy listo.",
  str_homestory_N24diaoyu_90050104X_4_option_content = "Aún no.",
  str_homestory_N24diaoyu_90050105_1_dialog_content = "Eres bastante bueno en esto, PlayerName.",
  str_homestory_N24diaoyu_90050105_2_dialog_content = "Seguro que eres un natural en la pesca, PlayerName.",
  str_homestory_N24diaoyu_90050105_3_dialog_content = "<sprite=emo_guilian size=60 />Jejeje, no es solo eso. ¡Tenía mucha práctica en Cloud Gardens!",
  str_homestory_N24diaoyu_90050105_4_dialog_content = "(Eso, y mucha gente me pidió que les consiguiera todo tipo de pescado).",
  str_homestory_N24diaoyu_90050105_5_dialog_content = "¿Eh? Ustedes son tan rápidos. Solo atrapé lo suficiente ahora.",
  str_homestory_N24diaoyu_90050105_6_dialog_content = "Está bien, Vice. Todos te estamos esperando.",
  str_homestory_N24diaoyu_90050105_7_dialog_content = "Aquí está tu caña de pescar. ¡Ahora eres un pescador!",
  str_homestory_N24diaoyu_90050105_8_dialog_content = "Entonces, espero verte en el concurso—",
  str_homestory_N24diaoyu_90050105_9_dialog_content = "Para el campeón—",
  str_homestory_N24diaoyu_90050105_10_dialog_content = "Para el museo—",
  str_homestory_N24diaoyu_90050105_11_dialog_content = "Para el Lumamber—",
  str_homestory_N24diaoyu_90050105_12_dialog_content = "<sprite=emo_caitiao size=60 />¡Buena suerte!",
  str_homestory_N24diaoyu_90050201_1_dialog_content = "Derecha. ¡Ahora que soy un pescador aprobado, comenzaré mi viaje para convertirme en el campeón!",
  str_homestory_N24diaoyu_90050201_2_dialog_content = "¡Lo primero es lo primero!",
  str_homestory_N24diaoyu_90050201_3_dialog_content = "Mmm... Lo primero...",
  str_homestory_N24diaoyu_90050201_4_dialog_content = "<sprite=emo_xiaoku size=60 />Yo... no creo estar familiarizado con las reglas todavía.",
  str_homestory_N24diaoyu_90050201_5_dialog_content = "Eso es vergonzoso. Ir tras Bethel con preguntas después de ese tipo de discurso...",
  str_homestory_N24diaoyu_90050201_6_dialog_content = "Eso no es muy parecido a un campeón.",
  str_homestory_N24diaoyu_90050201_7_dialog_content = "Todo el mundo debe conocer las reglas, ¡así que es lo mismo si le pregunto a alguien más! ¡Derecha!",
  str_homestory_N24diaoyu_90050201_8_dialog_content = "¿Mmm? ¿No es Lilica esa de allá? Es de Umbraton y es una sabelotodo.",
  str_homestory_N24diaoyu_90050201_9_dialog_content = "Debería ir a preguntarle.",
  str_homestory_N24diaoyu_90050202_1_dialog_content = "Lilica.",
  str_homestory_N24diaoyu_90050202_2_dialog_content = "<sprite=emo_laba size=60 />lilica—",
  str_homestory_N24diaoyu_90050202_3_dialog_content = "¿Eh?",
  str_homestory_N24diaoyu_90050202_4_dialog_content = "Me asustaste...",
  str_homestory_N24diaoyu_90050202_5_dialog_content = "No esperaba encontrarte aquí, PlayerName.",
  str_homestory_N24diaoyu_90050202_6_dialog_content = "¡Se me acaba de ocurrir una idea extraordinaria para una escena!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050202_7_dialog_content = "¡Lamento entrometerme en tus pensamientos, entonces!",
  str_homestory_N24diaoyu_90050202_8_dialog_content = "Oh esta bien. Mi inspiración se estaba agotando de todos modos. Estaba a punto de tomarme un descanso.",
  str_homestory_N24diaoyu_90050202_9_dialog_content = "¿Entonces qué necesitas?",
  str_homestory_N24diaoyu_90050202_10_dialog_content = "En realidad, eres bastante sabelotodo por aquí.",
  str_homestory_N24diaoyu_90050202_11_dialog_content = "¿Vaya? Es un buen cumplido. ¿Por qué me estás fastidiando?",
  str_homestory_N24diaoyu_90050202_12_dialog_content = "¿Conoces un concurso de pesca llamado An Extraordinary Catch?",
  str_homestory_N24diaoyu_90050202_13_dialog_content = "Por supuesto. Es de lo que todo el mundo habla recientemente.",
  str_homestory_N24diaoyu_90050202_14_dialog_content = "Bien... Tal vez pueda escribir un guión sobre pesca.",
  str_homestory_N24diaoyu_90050202_15_dialog_content = "Los protagonistas son dos hermanos, y su padre es profesor. El hermano mayor es un hombre bueno y honesto y heredó el negocio familiar después de graduarse.",
  str_homestory_N24diaoyu_90050202_16_dialog_content = "Y el hermano menor es romántico y adora la naturaleza. Aprendió un método especial de pesca.",
  str_homestory_N24diaoyu_90050202_17_dialog_content = "Sin embargo, era adicto al juego y solo salió de él con la ayuda de su hermano.",
  str_homestory_N24diaoyu_90050202_18_dialog_content = "E-Espera un minuto... Podrías hacerlo más tarde.",
  str_homestory_N24diaoyu_90050202_19_dialog_content = "Después me cuentas las reglas del concurso, si sabes.",
  str_homestory_N24diaoyu_90050202_20_dialog_content = "Pero el hermano mayor desapareció y el hermano menor atrapó un tiburón durante un viaje de pesca.",
  str_homestory_N24diaoyu_90050202_21_dialog_content = "Encontró el cuerpo de su hermano en el vientre del tiburón, y esto se convirtió en un extraño caso de asesinato.",
  str_homestory_N24diaoyu_90050202_22_dialog_content = "¡Vaya! Derecha. Me estás preguntando sobre las reglas. Claro, puedo ayudarte.",
  str_homestory_N24diaoyu_90050202_23_dialog_content = "¿En serio?",
  str_homestory_N24diaoyu_90050202_24_dialog_content = "Pero ya sabes cómo va. Tienes que hacer algo por mí.",
  str_homestory_N24diaoyu_90050202_25_dialog_content = "Reúne algo de madera para mí. Quiero construir un conjunto.",
  str_homestory_N24diaoyu_90050202_26_dialog_content = "Derecha. Volveré enseguida.",
  str_homestory_N24diaoyu_90050203_1_dialog_content = "¿Encontraste la madera? ¡Realmente estoy tratando de encontrar una buena trama aquí!",
  str_homestory_N24diaoyu_90050203_2_dialog_content = "¡Lo encontré! ({1}/{2})",
  str_homestory_N24diaoyu_90050203_3_dialog_content = "¡Buen trabajo!",
  str_homestory_N24diaoyu_90050203_4_dialog_content = "Solo un poco más. ¡Vuelve a pensar un rato más!",
  str_homestory_N24diaoyu_90050203_5_dialog_content = "Bien bien. Solo apúrate.",
  str_homestory_N24diaoyu_90050203_6_dialog_content = "¡Buen trabajo!",
  str_homestory_N24diaoyu_90050203_7_dialog_content = "Eso es rápido.",
  str_homestory_N24diaoyu_90050203_8_dialog_content = "Por supuesto. ¡Soy un maestro en hacer mandados ahora!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050203_9_dialog_content = "También fuiste muy útil anteriormente cuando filmabas la película. ¿Alguna vez consideró hacer algún trabajo en los sitios de tiro?",
  str_homestory_N24diaoyu_90050203_10_dialog_content = "<sprite=emo_hanshui size=60 />Jajaja... Lo pensaré un poco. Solo espero que sea más seguro la próxima vez.",
  str_homestory_N24diaoyu_90050203_11_dialog_content = "Jejeje Ya que eres un maestro en esto, ¿puedes traerme algo de pescado para la cena?",
  str_homestory_N24diaoyu_90050203_12_dialog_content = "Um... Ganaste bastante con la última película. ¿Por qué necesitas pescar para la cena en Cloud Gardens?",
  str_homestory_N24diaoyu_90050203_13_dialog_content = "¡Se llama ser frugal! Estoy ahorrando el dinero para la continuación de Into the Haunted House.",
  str_homestory_N24diaoyu_90050203_14_dialog_content = "Multa. Pensaré en ello como una práctica para el concurso. Sólo espérame aquí.",
  str_homestory_N24diaoyu_90050204_1_dialog_content = "¿Dónde está mi cena?",
  str_homestory_N24diaoyu_90050204_2_dialog_content = "¡Guau! Los peces se ven muy animados. ({1}/{2})",
  str_homestory_N24diaoyu_90050204_3_dialog_content = "Sólo un poco más. No es suficiente, ¿verdad?",
  str_homestory_N24diaoyu_90050204_4_dialog_content = "Oh, está bien. Todavía no tengo hambre. Puedes intentar atrapar un poco más, PlayerName.",
  str_homestory_N24diaoyu_90050204_5_dialog_content = "<sprite=emo_caitiao size=60 />¡Guau! Eso es mucho. Esto será suficiente por días.",
  str_homestory_N24diaoyu_90050204_6_dialog_content = "Hmm... ¿Planeas comer pescado todos los días durante los próximos días?",
  str_homestory_N24diaoyu_90050204_7_dialog_content = "También puedo pedirle a Cellulo que me traiga algo de fruta.",
  str_homestory_N24diaoyu_90050204_8_dialog_content = "(Mejor hago lo que dice Lilica.)",
  str_homestory_N24diaoyu_90050204_9_dialog_content = "(No quiero herir sus sentimientos diciendo lo que pienso.)",
  str_homestory_N24diaoyu_90050204_10_dialog_content = "Entonces... ¿Qué pasa con las reglas?",
  str_homestory_N24diaoyu_90050204_11_dialog_content = "¡Derecha! Casi olvido.",
  str_homestory_N24diaoyu_90050204_12_dialog_content = "No estás jugando conmigo, ¿verdad?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050204_13_dialog_content = "¡Bromear! ¡Yo sólo estoy bromeando!",
  str_homestory_N24diaoyu_90050204_14_dialog_content = "En realidad, yo mismo no conozco las reglas, pero conozco a alguien que sí.",
  str_homestory_N24diaoyu_90050204_15_dialog_content = "También tendrás que pasar por ella para convertirte en un verdadero pescador.",
  str_homestory_N24diaoyu_90050204_16_dialog_content = "¿A qué te refieres con eso?",
  str_homestory_N24diaoyu_90050204_17_dialog_content = "Fía. Es la instructora oficial y especialista del concurso.",
  str_homestory_N24diaoyu_90050204_18_dialog_content = "¿Qué... Fía? Acabo de rechazar su solicitud no hace mucho...",
  str_homestory_N24diaoyu_90050204_19_dialog_content = "¿Mmm? ¿Pasó algo entre ustedes dos?",
  str_homestory_N24diaoyu_90050204_20_dialog_content = "Ella no debería ser del tipo que guarda rencor, ¿verdad? Solo habla con ella.",
  str_homestory_N24diaoyu_90050204_21_dialog_content = "¡Si, tienes razón!",
  str_homestory_N24diaoyu_90050204_22_dialog_content = "Bueno, gracias, Lilica! ¡Te veré más tarde!<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050205_1_dialog_content = "Oye, Fia—",
  str_homestory_N24diaoyu_90050205_2_dialog_content = "<sprite=emo_emo size=60 />Bueno, ¿no es este el Sr. Curador del Museo, PlayerName?",
  str_homestory_N24diaoyu_90050205_3_dialog_content = "Pensé que eras un hombre ocupado.",
  str_homestory_N24diaoyu_90050205_4_dialog_content = "Hmm... ¿Todavía estás molesto?",
  str_homestory_N24diaoyu_90050205_5_dialog_content = "(¡Es hora de tomar la iniciativa de disculparse!)",
  str_homestory_N24diaoyu_90050205_6_dialog_content = "<sprite=emo_tanqi size=60 />Siento mucho lo de antes. ¡Fue mi error, y he aprendido de mi error!",
  str_homestory_N24diaoyu_90050205_7_dialog_content = "¡Humph! Así que no estás poniendo ninguna excusa. Bien.",
  str_homestory_N24diaoyu_90050205_8_dialog_content = "Estás aquí por el concurso, ¿no?",
  str_homestory_N24diaoyu_90050205_9_dialog_content = "Así es. ¡Sabía que no guardarías rencor, Fia!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050205_10_dialog_content = "No me agradezcas todavía. No he dicho que te voy a ayudar.",
  str_homestory_N24diaoyu_90050205_11_dialog_content = "Si quieres participar en el concurso, primero tienes que vencerme.",
  str_homestory_N24diaoyu_90050205_12_dialog_content = "Ahora, PlayerName, ¡Muéstrame lo que tienes!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050205X_1_dialog_content = "¿Ya podemos empezar? Soy una persona muy ocupada.",
  str_homestory_N24diaoyu_90050205X_2_option_content = "¡Sí!",
  str_homestory_N24diaoyu_90050205X_3_option_content = "¡De repente recordé que había algo que tenía que hacer!",
  str_homestory_N24diaoyu_90050206_1_dialog_content = "¡Eh...! Fia, no esperaba que fueras tan buena.",
  str_homestory_N24diaoyu_90050206_2_dialog_content = "¿Eh? Nada mal. Nada mal. Estoy impresionado, un poco. Pasaste.",
  str_homestory_N24diaoyu_90050206_3_dialog_content = "Ahora me siento un poco mejor después de un poco de ejercicio.",
  str_homestory_N24diaoyu_90050206_4_dialog_content = "Entonces te perdono por lo de antes.",
  str_homestory_N24diaoyu_90050206_5_dialog_content = "Pero, ¿no crees que di lo mejor de mí? Te dejo tranquilo.",
  str_homestory_N24diaoyu_90050206_6_dialog_content = "¿Me dejaste ir fácil? ¡Eres increíble, Fía!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050206_7_dialog_content = "¡Oh, ahora solo estás siendo un lamebotas!",
  str_homestory_N24diaoyu_90050206_8_dialog_content = "Será mejor que dediques algo de tiempo si quieres convertirte en el campeón.",
  str_homestory_N24diaoyu_90050206_9_dialog_content = "Ahora, ve y vence a tres <color=#FFB400>Maestros pescadores</color>!",
  str_homestory_N24diaoyu_90050206_10_dialog_content = "La puerta al campeonato solo se abrirá después de que derrotes a tres maestros pescadores.",
  str_homestory_N24diaoyu_90050206_11_dialog_content = "Esperaré sus resultados.",
  str_homestory_N24diaoyu_90050206_12_dialog_content = "¡Entendido!",
  str_homestory_N24diaoyu_90050301_1_dialog_content = "Oye, PlayerName!",
  str_homestory_N24diaoyu_90050301_2_dialog_content = "¿Brock? ¿Qué estás haciendo acá?",
  str_homestory_N24diaoyu_90050301_3_dialog_content = "El mismo de siempre. Entrenamiento diario, por supuesto.<sprite=emo_yaling size=60 />",
  str_homestory_N24diaoyu_90050301_4_dialog_content = "He estado entrenando incansablemente todos los días para prepararme para el trono de Rediesel Wrench.",
  str_homestory_N24diaoyu_90050301_5_dialog_content = "Bien... entonces me despediré de ti...",
  str_homestory_N24diaoyu_90050301_6_dialog_content = "Un momento.",
  str_homestory_N24diaoyu_90050301_7_dialog_content = "Oye, PlayerName, sosténgalo. ¿No crees que falta algo en Cloud Gardens?",
  str_homestory_N24diaoyu_90050301_8_dialog_content = "¿Mmm? ¿Qué falta?",
  str_homestory_N24diaoyu_90050301_9_dialog_content = "Si estás proponiendo algo, seguro que es inútil.<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050301_10_dialog_content = "<sprite=emo_shengqi size=60 />¡Oye! PlayerName! Cómo puedes decir eso? ¿No soy tu mejor amigo?",
  str_homestory_N24diaoyu_90050301_11_dialog_content = "¡Estoy siendo muy serio! ¡Lo menos que puedes hacer es escuchar!",
  str_homestory_N24diaoyu_90050301_12_dialog_content = "Bien, bien. Avanzar.",
  str_homestory_N24diaoyu_90050301_13_dialog_content = "¡Ejem! ¿No crees que necesitamos grandes instalaciones de entrenamiento físico aquí?",
  str_homestory_N24diaoyu_90050301_14_dialog_content = "Para un atleta como yo, es solitario y aburrido en Cloud Gardens.",
  str_homestory_N24diaoyu_90050301_15_dialog_content = "¿Por qué no encuentras un edificio y corres alrededor de él?",
  str_homestory_N24diaoyu_90050301_16_dialog_content = "Eso es aeróbico. ¡Lo que necesito es entrenamiento de resistencia de alta intensidad!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050301_17_dialog_content = "<sprite=emo_yihuo size=60 />¿Entrenamiento de alta intensidad... re-qué?",
  str_homestory_N24diaoyu_90050301_18_dialog_content = "¡Tráeme algunos minerales y construiré las máquinas de entrenamiento para ti!",
  str_homestory_N24diaoyu_90050301_19_dialog_content = "¿Eh? De ninguna manera. ¡Estoy ocupado en este momento!",
  str_homestory_N24diaoyu_90050301_20_dialog_content = "¿Ocupado haciendo qué? Estás ocupado tratando de localizar a un maestro pescador, ¿no es así?",
  str_homestory_N24diaoyu_90050301_21_dialog_content = "¿Cómo lo supiste?",
  str_homestory_N24diaoyu_90050301_22_dialog_content = "Todo lo que necesitas saber es: tú me ayudas y yo te ayudo.",
  str_homestory_N24diaoyu_90050301_23_dialog_content = "Bien... confiaré en ti.",
  str_homestory_N24diaoyu_90050302_1_dialog_content = "¿Tienes suficiente? ¡No puedo esperar!",
  str_homestory_N24diaoyu_90050302_2_dialog_content = "¡Bueno! Están todos aquí. ({1}/{2})",
  str_homestory_N24diaoyu_90050302_3_dialog_content = "Solo un poco más. Espera un poco más.",
  str_homestory_N24diaoyu_90050302_4_dialog_content = "¡Vamos! ¡Mi sangre está hirviendo ahora mismo!",
  str_homestory_N24diaoyu_90050302_5_dialog_content = "Bueno, debo decir que estás en muy buena forma. PlayerName.",
  str_homestory_N24diaoyu_90050302_6_dialog_content = "Deja de jugar conmigo. ¡Solo dime lo que necesito saber sobre el concurso!",
  str_homestory_N24diaoyu_90050302_7_dialog_content = "No te preocupes, te lo diré. Fleur es una maestra pescadora.",
  str_homestory_N24diaoyu_90050302_8_dialog_content = "¿Qué? ¿Fleur es un maestro pescador? Pensé que Rediesel Wrench está basada en el desierto...",
  str_homestory_N24diaoyu_90050302_9_dialog_content = "¿Y qué? ¿Entonces no son buenos para pescar gusanos de arena y cosas así?",
  str_homestory_N24diaoyu_90050302_10_dialog_content = "Será mejor que no lo subestimes solo porque es miembro de Rediesel Wrench.",
  str_homestory_N24diaoyu_90050302_11_dialog_content = "Eso lo aprendí por experiencia.",
  str_homestory_N24diaoyu_90050302_12_dialog_content = "Bueno. Iré a ver a Fleur, entonces.",
  str_homestory_N24diaoyu_90050302_13_dialog_content = "¡Luego!",
  str_homestory_N24diaoyu_90050303_1_dialog_content = "¡Fleur!",
  str_homestory_N24diaoyu_90050303_2_dialog_content = "Oh hola, PlayerName.",
  str_homestory_N24diaoyu_90050303_3_dialog_content = "¿Estás aquí para el evento de degustación?",
  str_homestory_N24diaoyu_90050303_4_dialog_content = "<sprite=emo_yihuo size=60 />¿Qué evento de degustación?",
  str_homestory_N24diaoyu_90050303_5_dialog_content = "Escuché de Brock que eres un maestro pescador. ¡Estoy aquí para desafiarte!",
  str_homestory_N24diaoyu_90050303_6_dialog_content = "Derecha. Me inscribí en ese evento, que regala una caña de pescar gratis, con el fin de recolectar ingredientes para la comida, y conseguí algunos peces...",
  str_homestory_N24diaoyu_90050303_7_dialog_content = "Supongo que así fue como me convertí en maestro pescador.",
  str_homestory_N24diaoyu_90050303_8_dialog_content = "Diciéndolo como si nada, supongo que realmente eres una buena pescadora, Fleur.",
  str_homestory_N24diaoyu_90050303_9_dialog_content = "Bueno, ¡no esperemos! PlayerName ¡El Dragonwave Angler te desafía!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050303_10_dialog_content = "Ahora no es el momento. Lo siento.",
  str_homestory_N24diaoyu_90050303_11_dialog_content = "¿Pero por qué?",
  str_homestory_N24diaoyu_90050303_12_dialog_content = "Como dije, estoy preparando los ingredientes de la comida para el evento de degustación.<sprite=emo_rou size=60 />",
  str_homestory_N24diaoyu_90050303_13_dialog_content = "Este es un nuevo método de cocción que acabo de aprender.",
  str_homestory_N24diaoyu_90050303_14_dialog_content = "Sirve pescados y mariscos frescos con un mínimo de condimentos para preservar el sabor original de los ingredientes de la comida.",
  str_homestory_N24diaoyu_90050303_15_dialog_content = "Sin embargo, simplemente no tengo suficientes ingredientes alimenticios. Que dolor de cabeza.",
  str_homestory_N24diaoyu_90050303_16_dialog_content = "¡Ayudaré!",
  str_homestory_N24diaoyu_90050303_17_dialog_content = "¿En serio? ¿Harías eso por mí?",
  str_homestory_N24diaoyu_90050303_18_dialog_content = "Si estás dispuesto a ayudar, me aseguraré de prepararlo para que podamos comenzar nuestra pequeña competencia. Cómo es eso, PlayerName?",
  str_homestory_N24diaoyu_90050303_19_dialog_content = "Consígueme un poco de pez globo. Puedes pensar en ello como un calentamiento, PlayerName.",
  str_homestory_N24diaoyu_90050303_20_dialog_content = "Déjamelo a mí.",
  str_homestory_N24diaoyu_90050304_1_dialog_content = "¿Obtuviste suficiente pez globo?",
  str_homestory_N24diaoyu_90050304_2_dialog_content = "¡Sí! ({1}/{2})",
  str_homestory_N24diaoyu_90050304_3_dialog_content = "Sólo unos pocos más. ¡Pronto los tendrás!",
  str_homestory_N24diaoyu_90050304_4_dialog_content = "Bueno. Muchas gracias.",
  str_homestory_N24diaoyu_90050304_5_dialog_content = "Gracias, PlayerName.",
  str_homestory_N24diaoyu_90050304_6_dialog_content = "Estos peces seguro que están frescos y vivos.",
  str_homestory_N24diaoyu_90050304_7_dialog_content = "¿Cómo vas a preparar el pescado?",
  str_homestory_N24diaoyu_90050304_8_dialog_content = "Bueno... diferentes peces requieren diferentes métodos.",
  str_homestory_N24diaoyu_90050304_9_dialog_content = "Algunos necesitan ser deshuesados, y la cabeza y los órganos internos que no son aptos para comer también deben ser removidos primero.",
  str_homestory_N24diaoyu_90050304_10_dialog_content = "Luego puedo filetear la hermosa carne e infundirla con Lumina para matar los parásitos allí.",
  str_homestory_N24diaoyu_90050304_11_dialog_content = "¡¿Puedes usar Lumina para eso?!<sprite=emo_cangshu size=60 />",
  str_homestory_N24diaoyu_90050304_12_dialog_content = "Sí. Es algo que acabo de aprender también.",
  str_homestory_N24diaoyu_90050304_13_dialog_content = "En cuanto al pez globo que acabas de traer, necesito extraer con cuidado los órganos internos, los ojos e incluso la sangre.",
  str_homestory_N24diaoyu_90050304_14_dialog_content = "En realidad, ahora que lo pienso, debe haber algunas personas en el evento a las que les moleste el pescado crudo.",
  str_homestory_N24diaoyu_90050304_15_dialog_content = "Comerlo crudo también podría causar indigestión en algunas personas.",
  str_homestory_N24diaoyu_90050304_16_dialog_content = "Me pregunto si puedes traerme un poco de agua fresca, PlayerName?",
  str_homestory_N24diaoyu_90050304_17_dialog_content = "Sería perfecto si pudiera preparar una sopa de pescado para todos.<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050304_18_dialog_content = "Entiendo.",
  str_homestory_N24diaoyu_90050305_1_dialog_content = "¿Tienes el agua?",
  str_homestory_N24diaoyu_90050305_2_dialog_content = "¡Sí, está hecho! ({1}/{2})",
  str_homestory_N24diaoyu_90050305_3_dialog_content = "No todavía. Dame un minuto.",
  str_homestory_N24diaoyu_90050305_4_dialog_content = "Por supuesto. Gracias.",
  str_homestory_N24diaoyu_90050305_5_dialog_content = "Un millón de gracias. Tendrás que esperarme un poco. Después de preparar la comida, ¿quieres probarla primero?",
  str_homestory_N24diaoyu_90050305_6_dialog_content = "¿En serio? No tenía mi... espera, ¡estoy aquí para desafiarte!",
  str_homestory_N24diaoyu_90050305_7_dialog_content = "Eso puede ser cierto, PlayerName. Elija uno para hacer primero, ¿comer o competir?",
  str_homestory_N24diaoyu_90050305_8_option_content = "Comer",
  str_homestory_N24diaoyu_90050305_9_dialog_content = "Excelente. Por favor espere aqui. La comida debe estar lista en dos horas.",
  str_homestory_N24diaoyu_90050305_10_dialog_content = "¿Así de largo? ¡Hagamos la competencia primero!",
  str_homestory_N24diaoyu_90050305_11_option_content = "Competir",
  str_homestory_N24diaoyu_90050305_12_dialog_content = "Ya veo. Si eso es lo que quieres, entonces ¡comencemos!",
  str_homestory_N24diaoyu_90050305X1_1_dialog_content = "¿Podemos empezar ahora? ¿O quieres comer algo primero?",
  str_homestory_N24diaoyu_90050305X1_2_option_content = "¡Está bien!",
  str_homestory_N24diaoyu_90050305X1_3_option_content = "Espera un segundo...",
  str_homestory_N24diaoyu_90050306_1_dialog_content = "<sprite=emo_xuanyun size=60 />Uf... Casi perdido.",
  str_homestory_N24diaoyu_90050306_2_dialog_content = "¡Jajaja! PlayerName, eres muy bueno!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050306_3_dialog_content = "Admito mi derrota. Me ganaste justo y cuadrado.",
  str_homestory_N24diaoyu_90050306_4_dialog_content = "Justo y cuadrado, ¿de verdad? Ahora me estás haciendo sospechar.",
  str_homestory_N24diaoyu_90050306_5_dialog_content = "De ninguna manera. Esta es una competencia honorable. Yo era muy serio al respecto.",
  str_homestory_N24diaoyu_90050306_6_dialog_content = "De todos modos, ahora has derrotado a un maestro pescador.",
  str_homestory_N24diaoyu_90050401_1_dialog_content = "Ahora que he descansado un poco, debería buscar al próximo maestro pescador.",
  str_homestory_N24diaoyu_90050401_2_dialog_content = "Hmm... Debería mirar alrededor y reunir algo de información primero.",
  str_homestory_N24diaoyu_90050401_3_dialog_content = "Oye, PlayerName!",
  str_homestory_N24diaoyu_90050401_4_dialog_content = "Hola, Bartón. ¿Qué es?",
  str_homestory_N24diaoyu_90050401_5_dialog_content = "Escuché que también eres un pescador, ¿verdad?",
  str_homestory_N24diaoyu_90050401_6_dialog_content = "Incluso derrotaste a Fleur, un maestro pescador. Nada mal. Nada mal.",
  str_homestory_N24diaoyu_90050401_7_dialog_content = "Gracias por el cumplido.",
  str_homestory_N24diaoyu_90050401_8_dialog_content = "No quiero sonar arrogante, pero sé un par de cosas sobre pesca.",
  str_homestory_N24diaoyu_90050401_9_dialog_content = "Si es así, hagamos una pequeña competencia amistosa.",
  str_homestory_N24diaoyu_90050401_10_dialog_content = "Realmente debería ayudarme que me enseñes una lección o dos.",
  str_homestory_N24diaoyu_90050401_11_dialog_content = "¿Vaya? ¿También te inscribiste en el concurso?",
  str_homestory_N24diaoyu_90050401_12_dialog_content = "Así es. Como fundador de Illumina Navy, la pesca es una habilidad requerida.",
  str_homestory_N24diaoyu_90050401_13_dialog_content = "Venir, PlayerName. Veamos lo que tienes.",
  str_homestory_N24diaoyu_90050401_14_dialog_content = "¡No seré fácil contigo!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050401_15_dialog_content = "<sprite=emo_daomei size=60 />Maldición... No esperaba que Barton fuera tan bueno en esto.",
  str_homestory_N24diaoyu_90050401_16_dialog_content = "Parece que tienes un largo camino por recorrer, debilucho.<sprite=emo_gezitou size=60 />",
  str_homestory_N24diaoyu_90050401_17_dialog_content = "Le falta convicción en su lanzamiento y tambaleo.",
  str_homestory_N24diaoyu_90050401_18_dialog_content = "Lo que es más importante es que estás lleno de dudas.",
  str_homestory_N24diaoyu_90050401_19_dialog_content = "Si no pudieras derrotarme, no podrías derrotar a otros maestros pescadores.",
  str_homestory_N24diaoyu_90050401_20_dialog_content = "Si esto es solo un juego para ti, ¡es mejor que lo dejes ahora!",
  str_homestory_N24diaoyu_90050401_21_dialog_content = "<sprite=emo_tanqi size=60 />Yo... ¿Cómo es posible que haya perdido?",
  str_homestory_N24diaoyu_90050401_22_dialog_content = "Incluso he superado a Fleur...",
  str_homestory_N24diaoyu_90050401_23_dialog_content = "Pero no puedo negar que Barton realmente es un profesional en esto.",
  str_homestory_N24diaoyu_90050401_24_dialog_content = "¡Necesito ser mejor! Pero como mejoro?",
  str_homestory_N24diaoyu_90050401_25_dialog_content = "Hombre...",
  str_homestory_N24diaoyu_90050401_26_dialog_content = "Oye, ¿no es esta mi pequeña Caelestite?",
  str_homestory_N24diaoyu_90050401_27_dialog_content = "Ay, azul...",
  str_homestory_N24diaoyu_90050401_28_dialog_content = "¿Por qué la cara larga? ¿Alguien te acosó?",
  str_homestory_N24diaoyu_90050401_29_dialog_content = "Yo... perdí la competencia de pesca con Barton.",
  str_homestory_N24diaoyu_90050401_30_dialog_content = "Entonces... ¿tú también te inscribiste en el concurso?",
  str_homestory_N24diaoyu_90050401_31_dialog_content = "Sí. Pero no soy lo suficientemente bueno para ganar.",
  str_homestory_N24diaoyu_90050401_32_dialog_content = "Me llené tanto de mí mismo solo porque superé a Fleur.",
  str_homestory_N24diaoyu_90050401_33_dialog_content = "Pero, en verdad, no estoy ni cerca de ser un profesional...",
  str_homestory_N24diaoyu_90050401_34_dialog_content = "Bien bien. ¿Has escuchado un dicho que dice \"el mal humor ahuyenta a los peces\"?",
  str_homestory_N24diaoyu_90050401_35_dialog_content = "Nunca. Te lo acabas de inventar, ¿no?",
  str_homestory_N24diaoyu_90050401_36_dialog_content = "¡Jajaja! Me tienes, pequeña Caelestite.<sprite=emo_aixin size=60 />",
  str_homestory_N24diaoyu_90050401_37_dialog_content = "¿Por qué no me haces un favor? Ve a dar un paseo o simplemente ve a hacer algo. Cualquier cosa.",
  str_homestory_N24diaoyu_90050401_38_dialog_content = "¿Qué tal si me traes un poco de agua?",
  str_homestory_N24diaoyu_90050401_39_dialog_content = "¿Agua? ¿Para qué necesitas agua?",
  str_homestory_N24diaoyu_90050401_40_dialog_content = "no preguntes Sólo hazme este favor.",
  str_homestory_N24diaoyu_90050402_1_dialog_content = "¿Tienes el agua?",
  str_homestory_N24diaoyu_90050402_2_dialog_content = "Bien. ({1}/{2})",
  str_homestory_N24diaoyu_90050402_3_dialog_content = "Bueno, eres rápido.",
  str_homestory_N24diaoyu_90050402_4_dialog_content = "Aún no...",
  str_homestory_N24diaoyu_90050402_5_dialog_content = "Animar. Prométeme que irás a buscar el agua primero.",
  str_homestory_N24diaoyu_90050402_6_dialog_content = "Ahora, baja el agua. ¿Cómo te sientes ahora?",
  str_homestory_N24diaoyu_90050402_7_dialog_content = "Hmm... No tan molesto como antes.",
  str_homestory_N24diaoyu_90050402_8_dialog_content = "UH Huh. ¿Sabes por qué se eligió Cloud Gardens como sede del concurso?",
  str_homestory_N24diaoyu_90050402_9_dialog_content = "Bueno... ¿Porque no me importa que se celebre un concurso de pesca aquí?",
  str_homestory_N24diaoyu_90050402_10_dialog_content = "Esa es una de las razones, pero no la razón.",
  str_homestory_N24diaoyu_90050402_11_dialog_content = "Es porque los peces aquí en Cloud Gardens son diferentes a los de cualquier otro lugar.",
  str_homestory_N24diaoyu_90050402_12_dialog_content = "Pueden sentir emociones cercanas. Si no está concentrado, o si no está determinado, ellos pueden sentir eso y ponerse alerta.",
  str_homestory_N24diaoyu_90050402_13_dialog_content = "Por eso se eligió este lugar para realizar el concurso.",
  str_homestory_N24diaoyu_90050402_14_dialog_content = "Y esa es también la razón por la que perdiste con Barton.",
  str_homestory_N24diaoyu_90050402_15_dialog_content = "Te falta convicción y concentración.",
  str_homestory_N24diaoyu_90050402_16_dialog_content = "Este concurso pone a prueba no solo tu técnica, sino también tu determinación y compromiso.",
  str_homestory_N24diaoyu_90050402_17_dialog_content = "¿E-es así?",
  str_homestory_N24diaoyu_90050402_18_dialog_content = "Barton también dijo algo similar hace un momento.",
  str_homestory_N24diaoyu_90050402_19_dialog_content = "¡Quiero ser mejor!<sprite=emo_yaling size=60 />",
  str_homestory_N24diaoyu_90050402_20_dialog_content = "Lo dijiste muy bien.",
  str_homestory_N24diaoyu_90050402_21_dialog_content = "Ven... pequeña Caelestite.",
  str_homestory_N24diaoyu_90050402_22_dialog_content = "Te enseñaré cómo sujetar la varilla correctamente.",
  str_homestory_N24diaoyu_90050402_23_dialog_content = "¡E-Espera! ¡Te estás acercando demasiado!",
  str_homestory_N24diaoyu_90050402_24_dialog_content = "Debes ser paciente. Esta es una lección muy seria.",
  str_homestory_N24diaoyu_90050402_25_dialog_content = "¡Tienes mucho que aprender para convertirte en el campeón!",
  str_homestory_N24diaoyu_90050402_26_dialog_content = "Bueno... debo decir que Azure me enseñó bastante sobre la pesca.",
  str_homestory_N24diaoyu_90050402_27_dialog_content = "¡Iré a desafiar a Barton de nuevo, ahora mismo!",
  str_homestory_N24diaoyu_90050403_1_dialog_content = "Oh, has vuelto, debilucho.<sprite=emo_gezitou size=60 />",
  str_homestory_N24diaoyu_90050403_2_dialog_content = "Esa es una buena mirada. Parece que tienes lo que se necesita ahora.",
  str_homestory_N24diaoyu_90050403_3_dialog_content = "Así es. El viejo yo está muerto. ¡Soy el nuevo yo!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050403_4_dialog_content = "¿Quieres hacerlo de nuevo?",
  str_homestory_N24diaoyu_90050403_5_option_content = "¡Hagámoslo!",
  str_homestory_N24diaoyu_90050403_6_option_content = "No estoy listo todavía.",
  str_homestory_N24diaoyu_90050404_1_dialog_content = "¡Puaj! ¡Perdí!",
  str_homestory_N24diaoyu_90050404_2_dialog_content = "No esperaba que pudieras crecer tanto en tan poco tiempo.",
  str_homestory_N24diaoyu_90050404_3_dialog_content = "<sprite=emo_woshou size=60 />Tengo que admitir que eres mejor que yo ahora.",
  str_homestory_N24diaoyu_90050404_4_dialog_content = "Las reglas son las reglas... Te daré el dinero que...",
  str_homestory_N24diaoyu_90050404_5_dialog_content = "¡Espera un minuto! ¡No hay reglas así! ¡Esto no es como la pelea en boxes de bestias maravillosas!",
  str_homestory_N24diaoyu_90050404_6_dialog_content = "Ah... Tienes razón.",
  str_homestory_N24diaoyu_90050404_7_dialog_content = "Luego, te diré dónde puedes encontrar al próximo maestro pescador.",
  str_homestory_N24diaoyu_90050405_1_dialog_content = "Este debería ser el lugar al que Barton me dijo que llegara.",
  str_homestory_N24diaoyu_90050405_2_dialog_content = "¿Mmm? ¿Por qué estás aquí, pequeña Caelestite?",
  str_homestory_N24diaoyu_90050405_3_dialog_content = "¿Ya venciste a Barton?",
  str_homestory_N24diaoyu_90050405_4_dialog_content = "¡Sí! ¡Gracias a ti, he superado a Barton!",
  str_homestory_N24diaoyu_90050405_5_dialog_content = "Esas son buenas noticias.",
  str_homestory_N24diaoyu_90050405_6_dialog_content = "Te das cuenta de que me debes una, ¿verdad?",
  str_homestory_N24diaoyu_90050405_7_dialog_content = "Jejeje! Te prometo que no lo olvidaré.",
  str_homestory_N24diaoyu_90050405_8_dialog_content = "Por cierto, el que habló Barton debería estar aquí... pero ¿dónde?",
  str_homestory_N24diaoyu_90050405_9_dialog_content = "La estás mirando.",
  str_homestory_N24diaoyu_90050405_10_dialog_content = "¿Eh? Te refieres a...",
  str_homestory_N24diaoyu_90050405_11_dialog_content = "Eso es exactamente lo que quiero decir.",
  str_homestory_N24diaoyu_90050405_12_dialog_content = "¿Qué? Espero que tu espíritu no se humedezca tan fácilmente.",
  str_homestory_N24diaoyu_90050405_13_dialog_content = "No... Pensé en la posibilidad de que pudieras ser tú.",
  str_homestory_N24diaoyu_90050405_14_dialog_content = "Pero no. Estoy confiado y comprometido. ¡Vamos a competir!<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050405_15_dialog_content = "Estoy tan aliviado.",
  str_homestory_N24diaoyu_90050405_16_dialog_content = "Déjame ver cuánto has mejorado.",
  str_homestory_N24diaoyu_90050405X_1_option_content = "Bueno, no me guardaré nada, entonces... ¡Vamos!",
  str_homestory_N24diaoyu_90050405X_2_option_content = "No, todavía tengo que practicar un poco más.",
  str_homestory_N24diaoyu_90050406_6_dialog_content = "Bueno, bueno, pensé que me debías un favor, pero realmente no dudaste.",
  str_homestory_N24diaoyu_90050406_7_dialog_content = "Porque sé que no querrías que fuera fácil contigo, especialmente en una competencia.",
  str_homestory_N24diaoyu_90050406_8_dialog_content = "Así es. Son dos cosas diferentes.",
  str_homestory_N24diaoyu_90050406_9_dialog_content = "Pero estoy realmente impresionado por cómo pudiste vencerme. Bien hecho.",
  str_homestory_N24diaoyu_90050406_10_dialog_content = "Y que ya no te molestan ni te afectan otras cosas.",
  str_homestory_N24diaoyu_90050406_11_dialog_content = "<sprite=emo_caitiao size=60 />Felicidades. Has derrotado a dos maestros pescadores. Ahora eres un gran pescador.",
  str_homestory_N24diaoyu_90050501_1_dialog_content = "Derecha. He vencido a dos maestros pescadores.",
  str_homestory_N24diaoyu_90050501_2_dialog_content = "A pesar de algunos contratiempos, sigo progresando bien.",
  str_homestory_N24diaoyu_90050501_3_dialog_content = "¡Ahora, todo lo que necesito es derrotar a un maestro pescador final para ganar!",
  str_homestory_N24diaoyu_90050501_4_dialog_content = "Debería ir a reunir información sobre el último maestro pescador.",
  str_homestory_N24diaoyu_90050501_5_dialog_content = "<sprite=emo_tanqi size=60 />*suspira*",
  str_homestory_N24diaoyu_90050501_6_dialog_content = "¿Eh? ¿Esta voz?",
  str_homestory_N24diaoyu_90050501_7_dialog_content = "¿Axelia? ¿Por qué estás aquí suspirando así?",
  str_homestory_N24diaoyu_90050501_8_dialog_content = "PlayerName...",
  str_homestory_N24diaoyu_90050501_9_dialog_content = "¿Es eso una caña de pescar para ti? Así que también eres un...",
  str_homestory_N24diaoyu_90050501_10_dialog_content = "Así es. ¡Soy el pescador Dragonwave!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050501_11_dialog_content = "Agradable.",
  str_homestory_N24diaoyu_90050501_12_dialog_content = "Estoy celosa.",
  str_homestory_N24diaoyu_90050501_13_dialog_content = "Celoso de cómo estás saludable y capaz de participar en un concurso de pesca, PlayerName.",
  str_homestory_N24diaoyu_90050501_14_dialog_content = "Estoy muy celoso.",
  str_homestory_N24diaoyu_90050501_15_dialog_content = "Um... ¿Por qué no te registras si también quieres unirte?",
  str_homestory_N24diaoyu_90050501_16_dialog_content = "Ya soy un pescador, en realidad.",
  str_homestory_N24diaoyu_90050501_17_dialog_content = "Pero quiero unirme a un escuadrón de pescadores.",
  str_homestory_N24diaoyu_90050501_18_dialog_content = "Lamentablemente, el líder del escuadrón me rechazó, diciendo que estoy demasiado deprimido.",
  str_homestory_N24diaoyu_90050501_19_dialog_content = "Estoy molesto, pero no es como si pudiera hacer algo al respecto.<sprite=emo_tanqi size=60 />",
  str_homestory_N24diaoyu_90050501_20_dialog_content = "¿¡Qué!? ¿Qué clase de excusa es esa?",
  str_homestory_N24diaoyu_90050501_21_dialog_content = "¡No hay posibilidad de que te deje así ahora que lo sé! Venir. ¡Hablaré con el líder de escuadrón!",
  str_homestory_N24diaoyu_90050502_1_dialog_content = "Ya estamos acá.",
  str_homestory_N24diaoyu_90050502_2_dialog_content = "¡Ahora veamos quién es el que se atrevió a intimidar a Axelia!",
  str_homestory_N24diaoyu_90050502_3_dialog_content = "¿Quién está causando todo el ruido y la conmoción?",
  str_homestory_N24diaoyu_90050502_4_dialog_content = "¿eh? ¿Qué es esa voz familiar?",
  str_homestory_N24diaoyu_90050502_5_dialog_content = "E-Espera... ¿¡Fia!?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050502_6_dialog_content = "Vaya, PlayerName.",
  str_homestory_N24diaoyu_90050502_7_dialog_content = "¿Cómo va el concurso? No seas un llorón solo porque perdiste con otros concursantes.",
  str_homestory_N24diaoyu_90050502_8_dialog_content = "¡De ninguna manera! ¡Ya he vencido a dos maestros pescadores!",
  str_homestory_N24diaoyu_90050502_9_dialog_content = "¡Tanto Fleur como Azure están impresionados con mis habilidades!",
  str_homestory_N24diaoyu_90050502_10_dialog_content = "¡Y también he superado a Barton!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050502_11_dialog_content = "(Aunque Barton me avergonzó primero).",
  str_homestory_N24diaoyu_90050502_12_dialog_content = "Vaya, estoy realmente impresionado. No pensé que lo tuvieras en ti, PlayerName.",
  str_homestory_N24diaoyu_90050502_13_dialog_content = "Iba a contarte más sobre los peces aquí para ayudarte.",
  str_homestory_N24diaoyu_90050502_14_dialog_content = "Realmente soy un buen pescador. No necesito eso para ganar... Espera, no estoy aquí para eso.",
  str_homestory_N24diaoyu_90050502_15_dialog_content = "¿Entonces, porque estas aqui?",
  str_homestory_N24diaoyu_90050502_16_dialog_content = "Fia, ¿se te ocurrió un escuadrón o algo así?",
  str_homestory_N24diaoyu_90050502_17_dialog_content = "¡Ciertamento lo hice! ¡El equipo de casa llena!",
  str_homestory_N24diaoyu_90050502_18_dialog_content = "¿Por qué no dejaste que Axelia se uniera?",
  str_homestory_N24diaoyu_90050502_19_dialog_content = "...",
  str_homestory_N24diaoyu_90050502_20_dialog_content = "Bueno... E-Eso es porque...",
  str_homestory_N24diaoyu_90050502_21_dialog_content = "Su personalidad realmente no encaja con nuestro equipo.",
  str_homestory_N24diaoyu_90050502_22_dialog_content = "¡Y mírala! El color de su ropa es similar a lo que estoy usando.",
  str_homestory_N24diaoyu_90050502_23_dialog_content = "¡El color personal único es muy importante para los miembros de este escuadrón!",
  str_homestory_N24diaoyu_90050502_24_dialog_content = "Pero no le has dado la oportunidad de mostrar sus habilidades, ¿verdad?",
  str_homestory_N24diaoyu_90050502_25_dialog_content = "¿Crees que es correcto juzgar un libro por su portada?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050502_26_dialog_content = "¿¡Por qué de repente te pones nervioso de esa manera!?",
  str_homestory_N24diaoyu_90050502_27_dialog_content = "Quiero decir, hay requisitos para unirse al equipo. Si ella realmente tiene lo que se necesita, ¡entonces demuéstralo!",
  str_homestory_N24diaoyu_90050502_28_dialog_content = "¡Ve a recoger algunos minerales, madera o pescado! ¡Solo muéstrame la prueba primero!",
  str_homestory_N24diaoyu_90050502_29_dialog_content = "No te preocupes, Axelia. Ve a recoger los minerales y la madera. Te ayudaré con el pescado.",
  str_homestory_N24diaoyu_90050502_30_dialog_content = "Gracias, PlayerName.",
  str_homestory_N24diaoyu_90050503_1_dialog_content = "¿Lo tienes todo?",
  str_homestory_N24diaoyu_90050503_2_dialog_content = "¡Tráelos aquí! ({1}/{2})",
  str_homestory_N24diaoyu_90050503_3_dialog_content = "¿Vaya? ¿Los tienes todos tan rápido?",
  str_homestory_N24diaoyu_90050503_4_dialog_content = "Aún no.",
  str_homestory_N24diaoyu_90050503_5_dialog_content = "Puedes rendirte en cualquier momento.",
  str_homestory_N24diaoyu_90050503_6_dialog_content = "Multa. Admito que te juzgué demasiado rápido. Es posible que tengas lo que se necesita para estar en el equipo.",
  str_homestory_N24diaoyu_90050503_7_dialog_content = "Esa es una gran noticia, Axelia.",
  str_homestory_N24diaoyu_90050503_8_dialog_content = "Gracias por ayudarme, PlayerName.",
  str_homestory_N24diaoyu_90050503_9_dialog_content = "<sprite=emo_wuzui size=60 />Esperar. Hizo PlayerName ayudar a reunirlos?",
  str_homestory_N24diaoyu_90050503_10_dialog_content = "Sí. ¿Y qué?",
  str_homestory_N24diaoyu_90050503_11_dialog_content = "<sprite=emo_shengqi size=60 />¿Y qué? ¡Es una prueba para Axelia!",
  str_homestory_N24diaoyu_90050503_12_dialog_content = "¿¡Cómo puede contar si la ayudaste!?",
  str_homestory_N24diaoyu_90050503_13_dialog_content = "¿¡Ni siquiera te molestaste cuando te pedí ayuda antes, y ahora eres un corazón sangrante!?",
  str_homestory_N24diaoyu_90050503_14_dialog_content = "¡Estás exasperando!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050503_15_dialog_content = "¡E-Espera, Fia! ¡Pensé que habías dicho que me habías perdonado antes!",
  str_homestory_N24diaoyu_90050503_16_dialog_content = "¡Te perdoné temporalmente! ¡No lo dejes atrás!",
  str_homestory_N24diaoyu_90050503_17_dialog_content = "¡Humph! Parece que necesito ponerte en tu lugar, PlayerName!",
  str_homestory_N24diaoyu_90050503_18_dialog_content = "¡Hagámoslo como lo hacemos entre dos pescadores!",
  str_homestory_N24diaoyu_90050503_19_dialog_content = "¡Saca tu caña de pescar y no creas que esta vez seré fácil contigo!",
  str_homestory_N24diaoyu_90050503_20_dialog_content = "¡Te haré suplicar y llorar!",
  str_homestory_N24diaoyu_90050503X1_1_dialog_content = "Tu estupido PlayerName! ¡Ven aquí para que pueda vencerte!",
  str_homestory_N24diaoyu_90050503X1_2_option_content = "¡Nunca admitiré la derrota!",
  str_homestory_N24diaoyu_90050503X1_3_option_content = "No quiero competir ahora.",
  str_homestory_N24diaoyu_90050504_1_dialog_content = "<sprite=emo_hanshui size=60 />Huff... huff... Fia es realmente buena.",
  str_homestory_N24diaoyu_90050504_2_dialog_content = "¿Es esto lo que realmente tienes?",
  str_homestory_N24diaoyu_90050504_3_dialog_content = "Afortunadamente logré ganar, apenas. ¿Puedes calmarte ahora?",
  str_homestory_N24diaoyu_90050504_4_dialog_content = "<sprite=emo_xinsui size=60 />Yo... no puedo creerlo.",
  str_homestory_N24diaoyu_90050504_5_dialog_content = "Pero el honor lo es todo para un pescador. Interpretaré lo que pasó antes como una disculpa.",
  str_homestory_N24diaoyu_90050504_6_dialog_content = "Axelia, oficialmente te doy la bienvenida como el segundo miembro del equipo.",
  str_homestory_N24diaoyu_90050504_7_dialog_content = "Gracias. Lo haré lo mejor que pueda.",
  str_homestory_N24diaoyu_90050504_8_dialog_content = "(¿Qué? ¿Solo dos personas en el escuadrón? ¿Por qué quería unirse a este tipo de escuadrón, para empezar?)",
  str_homestory_N24diaoyu_90050504_9_dialog_content = "Eso es lo que yo llamo un buen final. Debería estar en camino de encontrar al próximo maestro pescador.",
  str_homestory_N24diaoyu_90050504_10_dialog_content = "¿Eh? ¿Qué será el próximo maestro pescador?",
  str_homestory_N24diaoyu_90050504_11_dialog_content = "Has superado a Fleur y Azure. Soy el único que queda.",
  str_homestory_N24diaoyu_90050504_12_dialog_content = "¿Qué? ¿Eres un maestro pescador? Pensé que eras el instructor.",
  str_homestory_N24diaoyu_90050504_13_dialog_content = "¿Quién dice que un instructor no puede ser un maestro pescador?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050504_14_dialog_content = "¿Golpeándome sin siquiera saber eso? Realmente eres exasperante, lo sabes.",
  str_homestory_N24diaoyu_90050504_15_dialog_content = "¡Venir! ¡Vamos a dar unas vueltas más!",
  str_homestory_N24diaoyu_90050601_1_dialog_content = "Mis manos están tan adoloridas. <sprite=emo_xuanyun size=60 />Arrastrado a pescar por Fia durante más de diez horas seguidas...",
  str_homestory_N24diaoyu_90050601_2_dialog_content = "¡Pero he vencido a tres maestros pescadores! PlayerName ¡El Dragonwave Angler triunfa de nuevo!",
  str_homestory_N24diaoyu_90050601_3_dialog_content = "¡Jajaja! ¡Ahora debería poder obtener la caña de pescar premiada, venderla y obtener el dinero para construir un museo!",
  str_homestory_N24diaoyu_90050601_4_dialog_content = "He estado compitiendo con otras personas durante mucho tiempo. Casi olvido el placer de pescar tranquilamente solo.",
  str_homestory_N24diaoyu_90050601_5_dialog_content = "Déjame hacer eso entonces, solo para relajarme.",
  str_homestory_N24diaoyu_90050601_6_dialog_content = "<sprite=emo_wuzui size=60 />¿¡Mmm!? ¡Esta fuerza!",
  str_homestory_N24diaoyu_90050601_7_dialog_content = "¡Un pez increíble acaba de morder el anzuelo!",
  str_homestory_N24diaoyu_90050601_8_dialog_content = "je!!",
  str_homestory_N24diaoyu_90050601_9_dialog_content = "<sprite=emo_baimao size=60 />Hmm... Miau.",
  str_homestory_N24diaoyu_90050601_10_dialog_content = "¿Q-Qué...",
  str_homestory_N24diaoyu_90050601_11_dialog_content = "Filishy!? ¿¡Cómo!?",
  str_homestory_N24diaoyu_90050601_12_dialog_content = "¿O es este un tipo de pez que se parece a Philyshy?",
  str_homestory_N24diaoyu_90050601_13_dialog_content = "O-Ay! Duele, PlayerName! ¡Soy yo, Filishy! ¡Maullar!<sprite=emo_baimao size=60 />",
  str_homestory_N24diaoyu_90050601_14_dialog_content = "Pero... ¿Por qué serías atrapado por mí como un pez?",
  str_homestory_N24diaoyu_90050601_15_dialog_content = "¿Importa ahora? ¡Date prisa, miau! ¡Entregue este documento a la oficial Vivian de mi parte!",
  str_homestory_N24diaoyu_90050602_1_dialog_content = "¡Oficial Viviana!",
  str_homestory_N24diaoyu_90050602_2_dialog_content = "PlayerName? ¿Por qué tienes tanta prisa?",
  str_homestory_N24diaoyu_90050602_3_dialog_content = "¡E-Esto! Philyshy me pidió que te entregara esto lo antes posible.",
  str_homestory_N24diaoyu_90050602_4_dialog_content = "¿Eh? Phillyshy, dices?",
  str_homestory_N24diaoyu_90050602_5_dialog_content = "Déjame ver... Hmm, esto debería haber estado en mi escritorio ayer.",
  str_homestory_N24diaoyu_90050602_6_dialog_content = "<sprite=emo_shengqi size=60 />Phillyshy... A veces realmente me pregunto qué ha estado haciendo.",
  str_homestory_N24diaoyu_90050602_7_dialog_content = "Um... Hay algo que no sé si debo decir o no.",
  str_homestory_N24diaoyu_90050602_8_dialog_content = "Me encontré con ella cuando estaba pescando.",
  str_homestory_N24diaoyu_90050602_9_dialog_content = "¿¡Está holgazaneando y pescando!?",
  str_homestory_N24diaoyu_90050602_10_dialog_content = "No no. ¿Cómo debo ponerlo? No es que estuviera pescando.",
  str_homestory_N24diaoyu_90050602_11_dialog_content = "La saqué del agua...",
  str_homestory_N24diaoyu_90050602_12_dialog_content = "...",
  str_homestory_N24diaoyu_90050602_13_dialog_content = "No importa. PlayerName, ¿serías tan amable de volver con Philyshy y decirle que venga aquí?",
  str_homestory_N24diaoyu_90050603_1_dialog_content = "Phillyshy, he vuelto.",
  str_homestory_N24diaoyu_90050603_2_dialog_content = "¿Le entregaste el documento a la Oficial Vivian? ¡Gracias! ¡Maullar!",
  str_homestory_N24diaoyu_90050603_3_dialog_content = "Pero todavía no entiendo por qué estabas en el agua y terminaste en el otro extremo de mi caña de pescar.",
  str_homestory_N24diaoyu_90050603_4_dialog_content = "Bueno... probablemente estaba tratando de pescar, holgazaneando... o soñando despierto.",
  str_homestory_N24diaoyu_90050603_5_dialog_content = "N-No es que importe, miau.",
  str_homestory_N24diaoyu_90050603_6_dialog_content = "Escuché que has vencido a tres maestros pescadores, PlayerName.",
  str_homestory_N24diaoyu_90050603_7_dialog_content = "¿Ya escuchaste eso?",
  str_homestory_N24diaoyu_90050603_8_dialog_content = "Vamos, soy un oficial de inteligencia, miau.<sprite=emo_emo size=60 />",
  str_homestory_N24diaoyu_90050603_9_dialog_content = "Así es. He derrotado a tres maestros pescadores, ¡así que soy el campeón!",
  str_homestory_N24diaoyu_90050603_10_dialog_content = "<sprite=emo_yihuo size=60 />¿Eh? Pero aún no has vencido al campeón.",
  str_homestory_N24diaoyu_90050603_11_dialog_content = "¿Qué? Pensé que ganaría automáticamente el evento después de derrotar a los tres maestros pescadores.",
  str_homestory_N24diaoyu_90050603_12_dialog_content = "¡Claro que no, miau!",
  str_homestory_N24diaoyu_90050603_13_dialog_content = "¡Tienes que derrotar al campeón anterior!",
  str_homestory_N24diaoyu_90050603_14_dialog_content = "Um... Nadie se molestó en decirme eso.",
  str_homestory_N24diaoyu_90050603_15_dialog_content = "Caray.",
  str_homestory_N24diaoyu_90050603_16_dialog_content = "Bueno, para agradecerte por ayudarme, te diré dónde puedes encontrar al campeón.",
  str_homestory_N24diaoyu_90050603_17_dialog_content = "¡Gracias!",
  str_homestory_N24diaoyu_90050603_18_dialog_content = "Por cierto, la oficial Vivian te está buscando.",
  str_homestory_N24diaoyu_90050603_19_dialog_content = "*Sollozos* Lo sé, miau... Todavía no puedo evitarla, ¿verdad?",
  str_homestory_N24diaoyu_90050604_1_dialog_content = "Eh...? ¿Beretta? ¿Eres el actual campeón?",
  str_homestory_N24diaoyu_90050604_2_dialog_content = "¿Estás hablando del concurso de pesca?",
  str_homestory_N24diaoyu_90050604_3_dialog_content = "Recuerdo haberlo hecho, seguro...",
  str_homestory_N24diaoyu_90050604_4_dialog_content = "La pesca es divertida, y creo que superé a unos cientos de otros pescadores sin que yo lo supiera realmente.",
  str_homestory_N24diaoyu_90050604_5_dialog_content = "Y luego de alguna manera me convertí en el campeón, no es que me importe un título como ese.<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050604_5X1_dialog_content = "Entonces, ¿estás aquí para desafiarme?",
  str_homestory_N24diaoyu_90050604_6_dialog_content = "Um... Decirlo como si nada, lo mejor siempre es así, supongo.",
  str_homestory_N24diaoyu_90050604_7_option_content = "¡A ver quién es mejor entre nosotros!",
  str_homestory_N24diaoyu_90050604_8_option_content = "Necesito hacer más preparativos.",
  str_homestory_N24diaoyu_90050605_1_dialog_content = "<sprite=emo_daomei size=60 />Eh...! ¿Cómo es eso posible?",
  str_homestory_N24diaoyu_90050605_2_dialog_content = "eres bastante bueno, PlayerName. Supongo que debo tomarte más en serio.",
  str_homestory_N24diaoyu_90050605_3_dialog_content = "No hay competencia en absoluto. Los peces simplemente van a Beretta como si fuera un imán de peces o algo así.",
  str_homestory_N24diaoyu_90050605_4_dialog_content = "No hay forma de que pueda ganar.",
  str_homestory_N24diaoyu_90050605_5_dialog_content = "¿Es este el final de mi racha ganadora...?<sprite=emo_xinsui size=60 />",
  str_homestory_N24diaoyu_90050605_6_dialog_content = "PlayerName, no te vas a rendir ya, ¿verdad?",
  str_homestory_N24diaoyu_90050605_7_dialog_content = "¿Olvidaste nuestra promesa?",
  str_homestory_N24diaoyu_90050605_8_dialog_content = "¡Vice! ¡Carleen!",
  str_homestory_N24diaoyu_90050605_9_dialog_content = "PlayerName, ¡Síguelo! ¡Te prepararé un festín de mariscos si ganas!",
  str_homestory_N24diaoyu_90050605_10_dialog_content = "Oye, parecer derrotado no es un buen aspecto para mi pequeña Caelestite. ¡Agárralo!",
  str_homestory_N24diaoyu_90050605_11_dialog_content = "¡Vamos! me has superado, PlayerName. ¡No hay manera de que vayas a perder con ella!",
  str_homestory_N24diaoyu_90050605_12_dialog_content = "<sprite=emo_daku size=60 />Fleur... Azure... y Fia... Están todos aquí.",
  str_homestory_N24diaoyu_90050605_13_dialog_content = "No te perdonaremos si te rindes así. PlayerName!",
  str_homestory_N24diaoyu_90050605_14_dialog_content = "¡Eso es todo! Te voy a llevar al gimnasio conmigo, PlayerName. ¡Acabo de hacer unas mancuernas!",
  str_homestory_N24diaoyu_90050605_15_dialog_content = "Barton, tú también...",
  str_homestory_N24diaoyu_90050605_16_dialog_content = "Gracias por estar aquí para mí, todos.<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050605_17_dialog_content = "¿Por qué me haces parecer el último jefe villano...?",
  str_homestory_N24diaoyu_90050605_18_dialog_content = "¡Oye! No me estás ignorando, ¿verdad?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050605_19_dialog_content = "¡Gracias a todos... por animarme!",
  str_homestory_N24diaoyu_90050605_20_dialog_content = "¡Ahora, déjame mostrarte la primera y última habilidad definitiva del Dragonwave Angler!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050605X_1_dialog_content = "¿Quieres desafiarme de nuevo? Realmente no me importa.",
  str_homestory_N24diaoyu_90050605X_2_option_content = "¡Para nuestros compañeros!",
  str_homestory_N24diaoyu_90050605X_3_option_content = "¡Solo un poco más largo!",
  str_homestory_N24diaoyu_90050606_1_dialog_content = "Oh... Así que esto es lo que es perder...",
  str_homestory_N24diaoyu_90050606_2_dialog_content = "Gané... ¡Finalmente he ganado!",
  str_homestory_N24diaoyu_90050606_3_dialog_content = "Felicidades, PlayerName!<sprite=emo_caitiao size=60 />",
  str_homestory_N24diaoyu_90050606_4_dialog_content = "Impresionante, PlayerName!",
  str_homestory_N24diaoyu_90050606_5_dialog_content = "Estoy conmovido.<sprite=emo_daku size=60 />",
  str_homestory_N24diaoyu_90050606_6_dialog_content = "¡Realmente diste todo lo que tienes!",
  str_homestory_N24diaoyu_90050606_7_dialog_content = "Cómo has crecido, mi pequeña Caelestite.<sprite=emo_aixin size=60 />",
  str_homestory_N24diaoyu_90050606_8_dialog_content = "Eso es mejor!",
  str_homestory_N24diaoyu_90050606_9_dialog_content = "<sprite=emo_sikao size=60 />¿¡Sigues ignorándome!?",
  str_homestory_N24diaoyu_90050606_10_dialog_content = "Gracias... Gracias a todos.",
  str_homestory_N24diaoyu_90050606_11_dialog_content = "Bien hecho... Así es PlayerName el nuevo campeón ahora?",
  str_homestory_N24diaoyu_90050606_12_dialog_content = "Sucede que traigo al anfitrión del evento conmigo. Podemos dar las recompensas ahora, ¿verdad?",
  str_homestory_N24diaoyu_90050606_13_dialog_content = "Bueno... Sobre eso...",
  str_homestory_N24diaoyu_90050606_14_dialog_content = "¿Jomu? ¿Fuiste tú quien le sugirió esto al editor?",
  str_homestory_N24diaoyu_90050606_15_dialog_content = "Estoy impresionado. No pensé que harías nada gratis.",
  str_homestory_N24diaoyu_90050606_16_dialog_content = "Por cierto, ¿dónde está mi premio? ¿Esa caña de pescar súper increíble?",
  str_homestory_N24diaoyu_90050606_17_dialog_content = "Sí, estaba llegando a eso...",
  str_homestory_N24diaoyu_90050606_18_dialog_content = "Ya sabes, el precio de Lumamber se disparó...",
  str_homestory_N24diaoyu_90050606_19_dialog_content = "Así que tuve que cambiar las gemas de la caña de pescar por los minerales sobrantes de Brock.",
  str_homestory_N24diaoyu_90050606_20_dialog_content = "Pero es lo que representa lo que importa, ¿verdad? Quiero decir, ¡es un símbolo de tu maestría!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050606_21_dialog_content = "Dar...",
  str_homestory_N24diaoyu_90050606_22_dialog_content = "¡Dame mi caña de pescar de oro puro Lumamber!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050901_1_dialog_content = "Ten una competencia con Carleen.",
  str_homestory_N24diaoyu_90050902_1_dialog_content = "Fantástico.",
  str_homestory_N24diaoyu_90050903_1_dialog_content = "Ella es la capitana...",
  str_homestory_N24diaoyu_90050904_1_dialog_content = "Ella se ve muy enojada.",
  str_homestory_N24diaoyu_90050905_1_dialog_content = "Escuchemos lo que tiene que decir primero.",
  str_homestory_N24diaoyu_90050906_1_dialog_content = "No tengo tiempo para explicar, miau. ¡Llévale esta información a la oficial Vivian primero por mí!",
  str_homestory_N24diaoyu_90050907_1_dialog_content = "Por favor ayúdame a llamar a Philyshy aquí.",
  str_homestory_N24diaoyu_90050908_1_dialog_content = "Como se esperaba de PlayerName! ¡Eres simplemente increíble!",
  str_homestory_N24diaoyu_90050909_1_dialog_content = "Nadie es tan hábil como tú, PlayerName.",
  str_homestory_N24diaoyu_90050910_1_dialog_content = "¡Brillante!",
  str_homestory_N24diaoyu_90050911_1_dialog_content = "Tenía razón sobre ti, pequeña Caelestite.",
  str_homestory_N24diaoyu_90050912_1_dialog_content = "No quiero admitirlo, pero PlayerName realmente es muy fuerte!",
  str_homestory_N24diaoyu_90050913_1_dialog_content = "¡Guau! ¡Qué competencia tan satisfactoria!",
  str_homestory_N24diaoyu_90050914_1_dialog_content = "Vamos si has terminado. ¡Hagamos ejercicio juntos!",
  str_homestory_N24diaoyu_90050915_1_dialog_content = "¡Carleen!",
  str_homestory_N24diaoyu_90050915_2_dialog_content = "¿Eh? ¿Qué es, PlayerName?",
  str_homestory_N24diaoyu_90050915_3_dialog_content = "Sigues mirándome como si tuvieras algo que decir.",
  str_homestory_N24diaoyu_90050915_4_dialog_content = "Sí, en realidad sí, pero me siento un poco...",
  str_homestory_N24diaoyu_90050915_5_dialog_content = "Siéntete libre de decir lo que tengas en mente.",
  str_homestory_N24diaoyu_90050915_6_dialog_content = "Entonces diré...",
  str_homestory_N24diaoyu_90050915_7_dialog_content = "Sí.",
  str_homestory_N24diaoyu_90050915_8_dialog_content = "Bueno...",
  str_homestory_N24diaoyu_90050915_9_dialog_content = "¿Qué?",
  str_homestory_N24diaoyu_90050915_10_dialog_content = "¿Has estado practicando la pesca en secreto, Carleen?",
  str_homestory_N24diaoyu_90050915_11_dialog_content = "...Me tienes.",
  str_homestory_N24diaoyu_90050915_12_dialog_content = "Tengo muchos testigos.",
  str_homestory_N24diaoyu_90050915_13_dialog_content = "Sí. Desde nuestra última ronda, he estado perfeccionando mis habilidades.",
  str_homestory_N24diaoyu_90050915_14_dialog_content = "Después de estudiarte, PlayerName, y todos los maestros pescadores, siento que he aprendido mucho.",
  str_homestory_N24diaoyu_90050915_15_dialog_content = "Incluso diría que ahora soy lo suficientemente bueno como para estar al nivel de cuando venciste a Beretta.",
  str_homestory_N24diaoyu_90050915_16_dialog_content = "¿En serio?",
  str_homestory_N24diaoyu_90050915_17_dialog_content = "Entonces, ¿quieres probarme?",
  str_homestory_N24diaoyu_90050915_18_dialog_content = "Por supuesto. ¡Fuiste mi primer oponente y un socio invaluable en mi búsqueda para ser el campeón!",
  str_homestory_N24diaoyu_90050915_19_dialog_content = "Me alegra que pienses eso. Vamos al río, entonces.",
  str_homestory_N24diaoyu_90050916_1_dialog_content = "¿Deberíamos empezar?",
  str_homestory_N24diaoyu_90050916_2_option_content = "¡Sí, no puedo esperar!",
  str_homestory_N24diaoyu_90050916_3_option_content = "Espera un segundo...",
  str_homestory_N24diaoyu_90050917_1_dialog_content = "Seguro que eres bueno, PlayerName... lo concedo.",
  str_homestory_N24diaoyu_90050917_2_dialog_content = "Has mejorado mucho, Carleen. Siento que si me resbalo aunque sea una vez, me ganarías.",
  str_homestory_N24diaoyu_90050917_3_dialog_content = "Mmm...",
  str_homestory_N24diaoyu_90050917_4_dialog_content = "Sáltate los cumplidos.",
  str_homestory_N24diaoyu_90050917_5_dialog_content = "Este es el pulpo de anillos azules que atrapé en la práctica. Tu puedes tenerlo.",
  str_homestory_N24diaoyu_90050917_6_dialog_content = "¿Estás seguro? Es raro, ya sabes.",
  str_homestory_N24diaoyu_90050917_7_dialog_content = "Estoy seguro. La próxima vez que atrape a otro será cuando te gane, PlayerName.",
  str_homestory_N24diaoyu_90050917_8_dialog_content = "Seguiré practicando también, ¡y seré aún mejor la próxima vez!",
  str_homestory_N24diaoyu_90050917_9_dialog_content = "Haremos otra ronda otra vez en algún momento.",
  str_homestory_N24diaoyu_90050917_10_dialog_content = "¡Lo tienes!",
  str_homestory_N24diaoyu_90050918_1_dialog_content = "He mejorado mis habilidades últimamente. Intentemoslo de nuevo.",
  str_homestory_N24diaoyu_90050918_2_option_content = "¡Vamos!",
  str_homestory_N24diaoyu_90050918_3_option_content = "Acabo de recordar que tengo algo que hacer.",
  str_homestory_N24diaoyu_90050919_1_dialog_content = "Está bien, te espero aquí."
}
return config
